import{c as i,Q as a,j as e,m as t}from"./chunks/framework.DGHXLY8X.js";const k=JSON.parse('{"title":"Compositing sources onto a canvas","description":"","frontmatter":{},"headers":[],"relativePath":"operating/composers.md","filePath":"operating/composers.md","lastUpdated":1780987164000}'),n={name:"operating/composers.md"};function o(p,s,l,h,c,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="compositing-sources-onto-a-canvas" tabindex="-1">Compositing sources onto a canvas <a class="header-anchor" href="#compositing-sources-onto-a-canvas" aria-label="Permalink to &quot;Compositing sources onto a canvas&quot;">​</a></h1><p>A composer reads one or more sources, composites them onto a fixed BGRA canvas, and republishes the canvas as a single upstream that streams can encode. This page covers creating a composer, editing its layout live, applying a per-input perspective effect, and previewing the result. For how composers fit between sources and streams, see <a href="./../reference/pipeline-model">the pipeline model</a>. For the composer binary path and other settings, see <a href="./../reference/config-toml">config.toml</a>.</p><p>All endpoints require Basic Auth. The examples use the default <code>videonode:videonode</code> credentials and port <code>8090</code>.</p><h2 id="create-a-composer" tabindex="-1">Create a composer <a class="header-anchor" href="#create-a-composer" aria-label="Permalink to &quot;Create a composer&quot;">​</a></h2><p>To create a composer with a canvas, inputs, and an initial layout, POST to <code>/api/composers</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8090/api/composers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;id&quot;: &quot;main-scene&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;canvas&quot;: {&quot;w&quot;: 1920, &quot;h&quot;: 1080, &quot;fps&quot;: 60, &quot;background&quot;: &quot;#1a1a2e&quot;},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;inputs&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      {&quot;ref&quot;: &quot;source:hdmi-slides&quot;},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      {&quot;ref&quot;: &quot;source:cam-host&quot;}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;layout&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      {&quot;input&quot;: &quot;source:hdmi-slides&quot;, &quot;x&quot;: 0,    &quot;y&quot;: 0,   &quot;w&quot;: 1920, &quot;h&quot;: 1080},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      {&quot;input&quot;: &quot;source:cam-host&quot;,    &quot;x&quot;: 1440, &quot;y&quot;: 720, &quot;w&quot;: 480,  &quot;h&quot;: 360}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>The <code>canvas.background</code> field accepts <code>#RRGGBB</code> or <code>#RRGGBBAA</code> hex; an empty value renders opaque black. Setting <code>fps</code> to <code>0</code> uses the daemon default of 60. Each <code>layout[].input</code> must match an <code>inputs[].ref</code> by name. Compositing only runs while the pipeline master switch is on.</p><h2 id="edit-the-layout-live" tabindex="-1">Edit the layout live <a class="header-anchor" href="#edit-the-layout-live" aria-label="Permalink to &quot;Edit the layout live&quot;">​</a></h2><p>To replace the full layout without restarting the composer, PATCH <code>/api/composers/{id}/layout</code>. The body is the complete replacement array, validated against the composer&#39;s inputs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8090/api/composers/main-scene/layout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;layout&quot;: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      {&quot;input&quot;: &quot;source:hdmi-slides&quot;, &quot;x&quot;: 0, &quot;y&quot;: 0, &quot;w&quot;: 1920, &quot;h&quot;: 1080,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;aspect_ratio_mode&quot;: &quot;fit&quot;},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      {&quot;input&quot;: &quot;source:cam-host&quot;, &quot;x&quot;: 1440, &quot;y&quot;: 720, &quot;w&quot;: 480, &quot;h&quot;: 360,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       &quot;rotation&quot;: 0}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>Each slot accepts <code>rotation</code> (clockwise degrees: <code>0</code>, <code>90</code>, <code>180</code>, or <code>270</code>) and <code>aspect_ratio_mode</code>:</p><ul><li><code>stretch</code> (default): fills the slot, ignoring the source aspect ratio.</li><li><code>fit</code>: letterboxes or pillarboxes to preserve aspect ratio.</li><li><code>crop</code>: fills the slot and clips the excess.</li></ul><p>Slot <code>x</code> and <code>y</code> may be negative; the off-canvas region is clipped.</p><h3 id="position-a-cropped-source" tabindex="-1">Position a cropped source <a class="header-anchor" href="#position-a-cropped-source" aria-label="Permalink to &quot;Position a cropped source&quot;">​</a></h3><p>When <code>aspect_ratio_mode</code> is <code>crop</code>, add a <code>crop</code> object to choose which part of the source fills the slot:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;input&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;source:cam-host&quot;,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x&quot;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1440,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;y&quot;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 720,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;w&quot;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 480,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;h&quot;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 360,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> &quot;aspect_ratio_mode&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;crop&quot;,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> &quot;crop&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {&quot;x&quot;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.5,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;y&quot;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.5,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;scale&quot;:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}}</span></span></code></pre></div><p><code>crop.x</code> and <code>crop.y</code> are normalized offsets (0 to 1, <code>0.5</code> is centered). <code>crop.scale</code> is an overfill factor (<code>&gt;= 1.0</code>, where <code>1.0</code> is the minimum fill). <code>crop</code> is ignored unless the mode is <code>crop</code>.</p><h2 id="apply-a-perspective-effect" tabindex="-1">Apply a perspective effect <a class="header-anchor" href="#apply-a-perspective-effect" aria-label="Permalink to &quot;Apply a perspective effect&quot;">​</a></h2><p>To warp one input into a four-corner quad, PATCH <code>/api/composers/{id}/inputs/{ref}/effect</code>. The <code>ref</code> path segment matches an <code>inputs[].ref</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8090/api/composers/main-scene/inputs/source:hdmi-slides/effect</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;effect&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;type&quot;: &quot;perspective&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;corners&quot;: [[40, 30], [1880, 60], [1840, 1040], [80, 1010]],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;snapshot_w&quot;: 1920,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;snapshot_h&quot;: 1080</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p><code>corners</code> lists the four points in <code>[top-left, top-right, bottom-right, bottom-left]</code> order, expressed in source pixel space. <code>snapshot_w</code> and <code>snapshot_h</code> declare that pixel space (typically the source&#39;s native resolution) so the composer normalizes the corners. <code>perspective</code> is the only effect type.</p><h3 id="clear-an-effect" tabindex="-1">Clear an effect <a class="header-anchor" href="#clear-an-effect" aria-label="Permalink to &quot;Clear an effect&quot;">​</a></h3><p>To remove the effect from an input, send an explicit <code>null</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8090/api/composers/main-scene/inputs/source:hdmi-slides/effect</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;effect&quot;: null}&#39;</span></span></code></pre></div><p>The <code>effect</code> field is required: omitting it returns <code>400</code>.</p><h2 id="preview-the-canvas" tabindex="-1">Preview the canvas <a class="header-anchor" href="#preview-the-canvas" aria-label="Permalink to &quot;Preview the canvas&quot;">​</a></h2><p>To fetch the latest rendered canvas frame as a JPEG, GET <code>/api/composers/{id}/snapshot.jpg</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8090/api/composers/main-scene/snapshot.jpg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> canvas.jpg</span></span></code></pre></div><p>The response carries an <code>ETag</code> of the form <code>&quot;frame-&lt;n&gt;&quot;</code>, so a conditional request with <code>If-None-Match</code> returns <code>304</code> when the frame has not advanced.</p><p>To watch a live multipart MJPEG stream of the canvas, GET <code>/api/composers/{id}/preview.mjpg</code>. Add <code>?fps=&lt;n&gt;</code> to cap the frame rate:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffplay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://videonode:videonode@localhost:8090/api/composers/main-scene/preview.mjpg?fps=10&quot;</span></span></code></pre></div><h2 id="delete-a-composer" tabindex="-1">Delete a composer <a class="header-anchor" href="#delete-a-composer" aria-label="Permalink to &quot;Delete a composer&quot;">​</a></h2><p>To delete a composer, DELETE <code>/api/composers/{id}</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videonode:videonode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8090/api/composers/main-scene</span></span></code></pre></div><p>The request returns <code>409</code> if any stream still references the composer; the error body lists the blocking stream IDs. Delete or repoint those streams first.</p>`,35)])])}const F=i(n,[["render",o]]);export{k as __pageData,F as default};
